def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]

    # Uniform lines whose color differs from the background mark separators.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]

    def bounds(n, separators):
        out, start = [], 0
        for s in separators:
            if start < s:
                out.append((start, s))
            start = s + 1
        if start < n:
            out.append((start, n))
        return out

    rs, cs = bounds(h, sep_rows), bounds(w, sep_cols)
    regions = [(r0, r1, c0, c1) for r0, r1 in rs for c0, c1 in cs]
    if not regions:
        return [row[:] for row in grid]

    # The region containing the most non-background cells is the pattern to repeat.
    source = max(regions, key=lambda b: sum(
        grid[r][c] != bg
        for r in range(b[0], b[1])
        for c in range(b[2], b[3])
    ))
    r0, r1, c0, c1 = source
    pattern = [grid[r][c0:c1] for r in range(r0, r1)]

    out = [row[:] for row in grid]
    for a, b, x, y in regions:
        if b - a == len(pattern) and y - x == len(pattern[0]):
            for i in range(b - a):
                out[a + i][x:y] = pattern[i][:]
    return out
